import type { DesiredJob, ExistingJob, ScheduleDefinition, StoredJobs } from './types';
import type { MaterializerTransaction } from '../materializer';
export interface ProvisionTransaction extends Pick<MaterializerTransaction, 'recordOccurrences' | 'retireSuperseded' | 'advanceJobs'> {
    findExisting(): Promise<ExistingJob[]>;
    insert(jobs: DesiredJob[]): Promise<number[]>;
    redefine(jobId: number, schedule: ScheduleDefinition, nextRunAt: Date | null): Promise<void>;
    withdrawPendingTasks(jobIds: number[]): Promise<void>;
    deleteJobs(jobIds: number[]): Promise<void>;
    readJobs(jobIds: number[]): Promise<StoredJobs>;
}
export type RunInProvisionTransaction = <T>(work: (tx: ProvisionTransaction) => Promise<T>) => Promise<T>;
export interface DeprovisionTransaction {
    deleteAll(): Promise<number>;
}
export type RunInDeprovisionTransaction = <T>(work: (tx: DeprovisionTransaction) => Promise<T>) => Promise<T>;
